import numpy as np
from scipy.optimize import minimize

def equations(vars):
    x, y, z = vars
    f1 = x**2 + y**2 + z**2 - 3
    f2 = x*y**3 + y*z**3 + z*x**3 - 3
    return f1**2 + f2**2

def verify(sol):
    x, y, z = sol
    f1 = x**2 + y**2 + z**2 - 3
    f2 = x*y**3 + y*z**3 + z*x**3 - 3
    return abs(f1) < 1e-6 and abs(f2) < 1e-6

# Use a grid of initial guesses to be more thorough
guesses = []
for x in np.linspace(-1.732, 1.732, 10):
    for y in np.linspace(-1.732, 1.732, 10):
        for z in np.linspace(-1.732, 1.732, 10):
            guesses.append((x, y, z))

unique_solutions = []
for guess in guesses:
    res = minimize(equations, guess, method='BFGS')
    if res.fun < 1e-10:
        sol = np.round(res.x, 8)
        if sol not in unique_solutions:
            if verify(sol):
                unique_solutions.append(sol)

print("Unique verified solutions:", unique_solutions)
print("Number of solutions:", len(unique_solutions))

